def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    # Start with cwd if path is relative
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[candidate]

            # If target is absolute, start from root
            if target.startswith('/'):
                current = '/'
                new_components = target.split('/')[1:]
            else:
                # Target is relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                new_components = target.split('/')

            # Insert remaining original components after the link target components
            components = new_components + components[i+1:]
            i = 0
            continue

        # Not a symlink, just update current
        current = candidate
        i += 1

    # Return result without trailing slash (except for '/')
    if current == '/':
        return '/'
    else:
        return current

